"""Build the local, searchable native-render review of the 56 imported assets."""
from pathlib import Path
import json
from PIL import Image, ImageDraw, ImageFont
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/verification/textbook-expansion-v1'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
rows=[]
captures=read(OUT/'final-captures/captures.json')
zh={'confucius':'孔子','qu_yuan':'屈原','chang_e':'嫦娥','jade_emperor':'玉皇大帝','socrates':'苏格拉底','tu_youyou':'屠呦呦','wang_yaping':'王亚平','yuan_longping':'袁隆平','zhang_heng':'幼年张衡','yu_gong':'愚公','nian':'年兽','santa_claus':'圣诞老人'}
font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
for row in sorted(read(ROOT/'assets/characters/textbook_expansion_v1/catalog.json')['assets'],key=lambda r:r['selection_code']):
 ident=row['id'];character=row['category']=='character'
 folder=ROOT/('assets/characters/textbook_expansion_v1' if character else 'assets/props/tripo_expansion_v1')/ident
 data=read(folder/('rig.json' if character else 'prop.json'))
 name=zh.get(ident.removeprefix('textbook_'),'')
 display=(name+' / '+row['name']) if name else row['name']
 if character:
  actions={a:min((p for p in captures if p['id']==ident and p['action']==a and p['view']=='front' and p.get('mode','normal')=='normal'),key=lambda p:abs(p['time']-at))['file'] for a,at in [('idle',0),('walk',.28),('greet_wave',.92),('pose_photo',.9)]}
  actions={a:'final-captures/'+p.removesuffix('-front.png') for a,p in actions.items()}
  review='final-captures/sheets/'+ident+'.jpg'
  glb=(folder/'character.glb').relative_to(ROOT).as_posix()
 else:
  key=ident.removeprefix('prop_');actions={'idle':'props/'+key+'-display'}
  review='props/'+key+'-review.jpg';glb=(folder/'prop.glb').relative_to(ROOT).as_posix()
  files=[p for mode in ['display','equipped'] for view in ['front','side','back'] if (p:=OUT/'props'/(key+'-'+mode+'-'+view+'.png')).exists()]
  sheet=Image.new('RGB',(1140,300*((len(files)+2)//3)),'#efede7');draw=ImageDraw.Draw(sheet)
  for i,p in enumerate(files):
   image=Image.open(p).convert('RGB');image.thumbnail((380,270));x=i%3*380;y=i//3*300
   sheet.paste(image,(x,y+30));draw.text((x+6,y+5),p.stem,font=font,fill='#2e4439')
  sheet.save(OUT/review,quality=92)
 rows.append(dict(id=ident,code=row['selection_code'],name=display,category=row['category'],kind=row['rig_type'],triangles=data['triangles'],bones=len(data.get('bones',[])),clips=len(data.get('actions',[])),glb='../../../'+glb,blend='../../../'+data['editable_source'],source='../../../'+row['source'],reference='../../../'+row['reference'],world=('world/'+ident+'.png') if character else None,original=row['original_filename'],sha256=row['source_sha256'],actions=actions,review=review))
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>56 件新增素材 · 字母岛</title>
<style>
:root{font-family:"Microsoft YaHei",system-ui,sans-serif;color:#233f34;background:#f1f0e9;color-scheme:light}*{box-sizing:border-box}body{margin:0}header,main,footer{max-width:1360px;margin:auto;padding:28px}header{padding-top:46px}.eyebrow{font-size:13px;letter-spacing:.12em;color:#617467}h1{font-size:clamp(30px,4vw,48px);letter-spacing:-.04em;margin:14px 0}p{line-height:1.8}a{color:#29634e;text-underline-offset:4px}nav,.links{display:flex;gap:16px;flex-wrap:wrap}.numbers{display:flex;gap:36px;margin:26px 0;font-size:14px}.numbers strong{font-size:32px;display:block;font-weight:600}.motion{border-top:1px solid #c8cec2;border-bottom:1px solid #c8cec2;padding:24px 0;display:grid;grid-template-columns:1.7fr 1fr;gap:30px;align-items:center}.motion video{width:100%;display:block;background:#dde5d9}.motion h2{font-size:25px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;position:sticky;top:0;padding:16px 0;background:#f1f0e9f5;z-index:1;border-bottom:1px solid #c8cec2}input,select{font:inherit;padding:10px 12px;border:1px solid #b9c4b5;border-radius:5px;background:#fafbf6;max-width:100%;color:inherit}input{width:270px}#count{margin-left:auto;color:#5c7264}#grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin-top:25px}article{background:#fafbf6;border:1px solid #d8dfd2;border-radius:6px;overflow:hidden}article img{width:100%;aspect-ratio:1.41;object-fit:contain;display:block;background:#e5e9df}article h2{font-size:20px;margin:4px 0 8px;line-height:1.4}.copy{padding:20px}.code{color:#6e7f70;font-size:12px;letter-spacing:.04em}.detail{font-size:13px;color:#627567;margin:10px 0 16px}.links{gap:10px 14px;font-size:14px}details{font-size:12px;overflow-wrap:anywhere;line-height:1.7;margin-top:16px;color:#72816e}summary{cursor:pointer}#empty{padding:40px 0;color:#6c7d6e}footer{border-top:1px solid #c8cec2;margin-top:25px;font-size:13px;color:#64786a}@media(max-width:950px){#grid{grid-template-columns:repeat(2,minmax(0,1fr))}.motion{grid-template-columns:1fr}.numbers{gap:22px}}@media(max-width:580px){header,main,footer{padding:20px}#grid{grid-template-columns:1fr}.numbers{justify-content:space-between;gap:10px}.numbers strong{font-size:26px}.toolbar{gap:8px}input{width:100%}#count{margin-left:0}select{font-size:14px}}
</style></head><body><header><div class="eyebrow">ALPHABET ISLAND / ASSET REVIEW</div><h1>新增素材，已经动起来了。</h1><p>48 个优先模型与 8 个章节候选已完成命名、整理与游戏导入。这里汇集 Godot 原生画面、三视角检查、原始模型和可编辑文件。</p><div class="numbers"><div><strong>40</strong>带骨架角色</div><div><strong>16</strong>场景与穿戴道具</div><div><strong>56</strong>原文件哈希保留</div></div><nav><a href="../../delivery/textbook-expansion-20261112.md">交付与检查记录</a><a href="../../../assets/tripo/generation_selection_20261112/model-renaming.json">原名与新名对照</a><a href="review.json">验证索引</a></nav></header><main><section class="motion"><video controls playsinline preload="metadata" poster="motion-poster.jpg" src="expansion-motion.mp4"></video><div><div class="eyebrow">NATIVE MOTION</div><h2>让身体结构决定动作</h2><p>双足角色使用 14 个动作；四足、鸟类和鱼类各有 6 个适配动作。长袍采用独立下摆控制，鱼类使用摆尾游泳。</p><p>预览依次展示人物、长袍、机器人，以及四足动物、鸟与鱼。完整三视角可在下方逐个打开。</p></div></section><div class="toolbar"><input id="search" type="search" aria-label="搜索素材" placeholder="搜索名字、编号或文件名"><select id="category" aria-label="素材类别"><option value="all">全部素材</option><option value="character">40 个角色</option><option value="prop">16 件道具</option></select><select id="action" aria-label="动作"><option value="idle">待机 / 展示</option><option value="walk">行走 / 游泳</option><option value="greet_wave">招呼</option><option value="pose_photo">拍照姿势</option><option value="reference">参考图</option><option value="world">正式场景</option></select><select id="view" aria-label="视角"><option value="front">正面</option><option value="side">侧面</option><option value="back">背面</option></select><span id="count"></span></div><div id="grid"></div><p id="empty" hidden>没有匹配的素材。</p></main><footer>画面来源：当前源项目 · Godot 4.7.2 / Vulkan Forward+。新角色已接入正式角色加载与动作入口，尚未逐章编排全部出场剧情。16 件道具已接入既有穿戴、持物和家具工厂。旧 Windows 导出包与网页构建未重新打包。</footer><script>
const rows=DATA;const el=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=el('search').value.trim().toLowerCase(),category=el('category').value,action=el('action').value,view=el('view').value;const chosen=rows.filter(r=>(category==='all'||r.category===category)&&[r.name,r.id,r.code,r.original].join(' ').toLowerCase().includes(q));el('count').textContent=chosen.length+' / 56 件';el('empty').hidden=chosen.length>0;el('grid').innerHTML=chosen.map(r=>{const src=action==='reference'?r.reference:action==='world'&&r.world?r.world:(r.actions[action]||r.actions.idle)+'-'+view+'.png';const type=({biped:'双足角色',robot:'机器人',quadruped:'四足动物',bird:'鸟类',fish:'鱼类',static:'道具'})[r.kind];return `<article data-id="${esc(r.id)}"><a href="${esc(src)}" target="_blank"><img loading="lazy" src="${esc(src)}" alt="${esc(r.name)} · ${action==='reference'?'参考图':el('action').selectedOptions[0].text+' / '+el('view').selectedOptions[0].text}"></a><div class="copy"><span class="code">${esc(r.code)} / ${type}</span><h2>${esc(r.name)}</h2><div class="detail">${r.triangles.toLocaleString()} 三角面${r.bones?' · '+r.bones+' 根骨骼 · '+r.clips+' 个动作':' · 挂点 / 场景摆放'}</div><div class="links"><a href="${esc(r.review)}" target="_blank">完整三视角</a>${r.world?`<a href="${esc(r.world)}" target="_blank">正式场景</a>`:''}<a href="${esc(r.glb)}" download>${r.bones?'绑定 GLB':'整理后 GLB'}</a><a href="${esc(r.blend)}" download>Blender</a><a href="${esc(r.source)}" download>原始模型</a></div><details><summary>文件名与来源</summary><p>${esc(r.id)}.glb<br>原名：${esc(r.original)}<br>SHA-256：${esc(r.sha256)}</p><a href="${esc(r.reference)}" target="_blank">对应参考图</a></details></div></article>`}).join('')}
for(const id of ['category','action','view'])el(id).addEventListener('change',render);el('search').addEventListener('input',render);render();
</script></body></html>'''
(OUT/'index.html').write_text(html.replace('DATA',json.dumps(rows,ensure_ascii=False)),encoding='utf-8')
(OUT/'gallery-data.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('EXPANSION_GALLERY',len(rows))
